class Solution:
    def findSmallestInteger(self, nums: list[int], value: int) -> int:
        from collections import Counter
        count = Counter((x % value) for x in nums)
        mex = 0
        while count[mex % value] > 0:
            count[mex % value] -= 1
            mex += 1
        return mex

class Solution {
public:
    int findSmallestInteger(std::vector<int>& nums, int value) {
        std::vector<int> count(value, 0);
        for (int x : nums) {
            int rem = ((x % value) + value) % value;
            count[rem]++;
        }
        int mex = 0;
        while (count[mex % value] > 0) {
            count[mex % value]--;
            mex++;
        }
        return mex;
    }
};

